result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "metrics.py", "content": """"Classification metrics implemented from scratch in NumPy.

Matches sklearn.metrics semantics:
- confusion_matrix with explicit n_classes
- precision/recall/F1 with micro, macro, weighted averaging
- per-class support (count of true occurrences)
- zero-division handled as 0 (no warnings, no NaN/inf)
"""

import numpy as np


def confusion_matrix(y_true, y_pred, n_classes):
    """Row = true class, column = predicted class."""
    y_true = np.asarray(y_true, dtype=np.int64).ravel()
    y_pred = np.asarray(y_pred, dtype=np.int64).ravel()
    if y_true.shape != y_pred.shape:
        raise ValueError("y_true and y_pred must have the same shape")
    cm = np.zeros((n_classes, n_classes), dtype=np.int64)
    np.add.at(cm, (y_true, y_pred), 1)
    return cm


def _check_inputs(y_true, y_pred):
    y_true = np.asarray(y_true, dtype=np.int64).ravel()
    y_pred = np.asarray(y_pred, dtype=np.int64).ravel()
    if y_true.shape != y_pred.shape:
        raise ValueError("y_true and y_pred must have the same shape")
    return y_true, y_pred


def precision_recall_fscore_support(y_true, y_pred, n_classes=None):
    """Per-class precision, recall, F1 and support.

    Zero-division is resolved to 0 for every metric.
    """
    y_true, y_pred = _check_inputs(y_true, y_pred)
    present = max(int(y_true.max()), int(y_pred.max()), -1) + 1
    if n_classes is None:
        n_classes = present
    elif n_classes < present:
        raise ValueError("n_classes smaller than labels present in data")

    tp = np.zeros(n_classes, dtype=np.float64)
    fp = np.zeros(n_classes, dtype=np.float64)
    fn = np.zeros(n_classes, dtype=np.float64)
    support = np.bincount(y_true, minlength=n_classes).astype(np.float64)

    correct = y_true == y_pred
    np.add.at(tp, y_true[correct], 1.0)
    # Predicted k but true j != k -> FP for k; use bincount on all preds minus TP.
    pred_counts = np.bincount(y_pred, minlength=n_classes).astype(np.float64)
    fp = pred_counts - tp
    fn = support - tp

    with np.errstate(divide="ignore", invalid="ignore"):
        precision = np.where(tp + fp > 0, tp / np.maximum(tp + fp, 1e-300), 0.0)
        recall = np.where(tp + fn > 0, tp / np.maximum(tp + fn, 1e-300), 0.0)
        f1 = np.where(
            precision + recall > 0,
            2 * precision * recall / np.maximum(precision + recall, 1e-300),
            0.0,
        )
    return precision, recall, f1, support


def accuracy_score(y_true, y_pred):
    y_true, y_pred = _check_inputs(y_true, y_pred)
    return float(np.mean(y_true == y_pred))


def _average(values, weights, average):
    values = np.asarray(values, dtype=np.float64)
    if average == "micro":
        raise ValueError("micro averaging must be handled by caller")
    if average == "macro":
        return float(np.mean(values))
    if average == "weighted":
        w = np.asarray(weights, dtype=np.float64)
        total = w.sum()
        if total == 0:
            return 0.0
        return float(np.sum(values * w) / total)
    raise ValueError(f"unknown average: {average}")


def _score_micro(tp_sum, sum_rows, sum_cols, kind):
    denom = {"precision": sum_cols, "recall": sum_rows}[kind]
    num = float(np.sum(tp_sum))
    den = float(np.sum(denom))
    return num / den if den > 0 else 0.0


def f1_score(y_true, y_pred, n_classes=None, average="macro"):
    p, r, f, s = precision_recall_fscore_support(y_true, y_pred, n_classes)
    if average in ("micro", "weighted"):
        pass
    if average == "micro":
        # For single-label multiclass, micro P = R = F1 = accuracy.
        return accuracy_score(y_true, y_pred)
    if average in ("macro", "weighted"):
        return _average(f, s, average)
    raise ValueError(f"unknown average: {average}")


def precision_score(y_true, y_pred, n_classes=None, average="macro"):
    p, r, f, s = precision_recall_fscore_support(y_true, y_pred, n_classes)
    if average == "micro":
        y_t, y_p = _check_inputs(y_true, y_pred)
        return float(np.mean(y_t == y_p))
    if average in ("macro", "weighted"):
        return _average(p, s, average)
    raise ValueError(f"unknown average: {average}")


def recall_score(y_true, y_pred, n_classes=None, average="macro"):
    p, r, f, s = precision_recall_fscore_support(y_true, y_pred, n_classes)
    if average == "micro":
        y_t, y_p = _check_inputs(y_true, y_pred)
        return float(np.mean(y_t == y_p))
    if average in ("macro", "weighted"):
        return _average(r, s, average)
    raise ValueError(f"unknown average: {average}")


def classification_report(y_true, y_pred, n_classes=None):
    """Convenience: dict of per-class metrics plus averaged summaries."""
    p, r, f, s = precision_recall_fscore_support(y_true, y_pred, n_classes)
    report = {
        "per_class": [
            {
                "class": i,
                "precision": float(p[i]),
                "recall": float(r[i]),
                "f1-score": float(f[i]),
                "support": int(s[i]),
            }
            for i in range(len(s))
        ],
        "accuracy": accuracy_score(y_true, y_pred),
        "macro avg": {
            "precision": _average(p, s, "macro"),
            "recall": _average(r, s, "macro"),
            "f1-score": _average(f, s, "macro"),
        },
        "weighted avg": {
            "precision": _average(p, s, "weighted"),
            "recall": _average(r, s, "weighted"),
            "f1-score": _average(f, s, "weighted"),
        },
    }
    return report
"})
